import { bigint, index, integer, pgTable, text, timestamp, uniqueIndex, uuid } from "drizzle-orm/pg-core";
import { createdAt, id } from "./common";
import { users } from "./users";

// Better Auth's own tables, written in our style (plural snake_case, uuid keys generated by the database).
// Better Auth finds them by the *property* names below (`userId`, `expiresAt`...), so those must stay as they
// are; only the column names (the strings) follow our snake_case convention.

const updatedAt = () =>
  timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

/**
 * One row per signed-in browser/phone. The cookie holds `token`; the server looks it up here.
 * `ON DELETE CASCADE`: deleting a user deletes their sessions too, so nothing is left dangling.
 */
export const sessions = pgTable(
  "sessions",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    token: text("token").notNull().unique(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  // Foreign keys are not indexed automatically in Postgres; sign-out-everywhere and cascades look up by user_id.
  (table) => [index("sessions_user_id_idx").on(table.userId)],
);

/**
 * One row per way of signing in for a user. Email + password is `provider_id = 'credential'` and keeps
 * the password *hash* in `password`; 
 */
export const accounts = pgTable(
  "accounts",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    // The user's id at the provider (for 'credential' it is our own user id).
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamp("access_token_expires_at", { withTimezone: true }),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at", { withTimezone: true }),
    scope: text("scope"),
    password: text("password"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    index("accounts_user_id_idx").on(table.userId),
    // The same provider identity cannot be attached to two rows.
    uniqueIndex("accounts_provider_account_unique").on(table.providerId, table.accountId),
  ],
);

/** Short-lived tokens (email verification, password reset). Unused in M3, but Better Auth expects the table. */
export const verifications = pgTable(
  "verifications",
  {
    id: id(),
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [index("verifications_identifier_idx").on(table.identifier)],
);

/**
 * Invite links (decision 0006). NOT user-scoped on purpose: an invite is checked *before* the person has a
 * user, so there is no user_id to filter by (`used_by_user_id` is only filled in afterwards, as a record of
 * who used it).
 *
 * Only a SHA-256 hash of the token is stored (`token_hash`), never the token: whoever reads this table, a
 * leaked backup included, cannot rebuild a working link. `unique` gives the hash an index, so looking an
 * invite up by its token is fast, and refuses two invites with the same hash.
 *
 * `used_at` null = still unused. A used invite is kept (not deleted) so the owner can see who joined.
 * `ON DELETE SET NULL`: if that user is deleted later the invite row stays, it just forgets who used it.
 */
export const invites = pgTable(
  "invites",
  {
    id: id(),
    tokenHash: text("token_hash").notNull().unique(),
    createdAt: createdAt(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    usedAt: timestamp("used_at", { withTimezone: true }),
    usedByUserId: uuid("used_by_user_id").references(() => users.id, { onDelete: "set null" }),
    // Free text for the owner ("for Ana"); not used by any logic.
    note: text("note"),
  },
  // Foreign keys are not indexed automatically in Postgres; the ON DELETE SET NULL above looks rows up by it.
  (table) => [index("invites_used_by_user_id_idx").on(table.usedByUserId)],
);

/**
 * Sign-in rate limiting (decision 0007). One row per "client IP + path": `count` requests so far in the window
 * that began at `last_request`. Better Auth keeps these counts here instead of in memory because Vercel runs
 * many short-lived server instances and each would otherwise count on its own, letting an attacker try 5 passwords
 * per instance. The database is the one place all instances share.
 *
 * `key` is unique, which gives it the index every lookup needs and lets Better Auth's insert-or-retry logic
 * detect two requests creating the same row at once. `last_request` is a bigint because it holds milliseconds
 * since 1970 (about 1.7 trillion), which does not fit in a 4-byte `integer` (max about 2.1 billion).
 * `mode: "number"` hands us a JS number; a millisecond timestamp is far below JS's safe integer limit.
 * No foreign key: the key is derived from an IP address, not from a user.
 */
export const rateLimits = pgTable("rate_limits", {
  id: id(),
  key: text("key").notNull().unique(),
  count: integer("count").notNull(),
  lastRequest: bigint("last_request", { mode: "number" }).notNull(),
});
